17	    }
18	}
19	
20	impl MarkdownReader {
21	    pub fn new() -> MarkdownReader {
22	        MarkdownReader {}
23	    }
24	}
25	
26	/// If `bare_frontmatter` is enabled and content starts with a YAML-like
27	/// `key: value` line (but not `---`), wrap the leading header block in `---`
28	/// fences so the downstream pulldown-cmark MetadataBlock machinery picks it up.
29	pub fn wrap_bare_frontmatter(content: &str) -> Cow<'_, str> {
30	    // Already fenced — leave alone.
31	    if content.starts_with("---") {
32	        return Cow::Borrowed(content);
33	    }
34	
35	    // Must start with a bare YAML key — `word: ` on the first line.
36	    // This avoids false positives on prose while accepting any key order
37	    // (e.g. TibbitWiki puts created/modified/tags before title).
38	    let first_line = content.lines().next().unwrap_or("");
39	    let is_yaml_key = first_line
40	        .find(": ")
41	        .map(|colon_pos| {
42	            // Everything before `: ` must be a simple key (alphanumeric, _, -)
43	            let key = &first_line[..colon_pos];
44	            !key.is_empty()
45	                && key
46	                    .bytes()
47	                    .all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-')
48	        })
49	        .unwrap_or(false);
50	    if !is_yaml_key {
51	        return Cow::Borrowed(content);
52	    }
53	
54	    // Find first true blank line (\n\n or \r\n\r\n).
55	    let (header, rest) = if let Some(pos) = content.find("\n\n") {
56	        (&content[..pos], &content[pos + 2..])
57	    } else if let Some(pos) = content.find("\r\n\r\n") {
58	        (&content[..pos], &content[pos + 4..])
59	    } else {
60	        // No blank line — entire content is header.
61	        (content.trim_end(), "")
62	    };
63	
64	    if rest.is_empty() {
65	        Cow::Owned(format!("---\n{}\n---\n", header))
66	    } else {
67	        Cow::Owned(format!("---\n{}\n---\n\n{}", header, rest))
68	    }
69	}
70	
71	impl Reader for MarkdownReader {
72	    fn document(&self, content: &str, markdown_options: &MarkdownOptions) -> Document {
73	        let effective = if markdown_options.bare_frontmatter {
74	            wrap_bare_frontmatter(content)
75	        } else {
76	            Cow::Borrowed(content)
77	        };
78	
79	        let mut reader = MarkdownEventsReader::new_with_options(markdown_options);
80	        reader.read(&effective);
81	
82	        Document {
83	            blocks: reader.blocks(),
84	            metadata: reader.metadata(),
85	        }
86	    }
87	}

